// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EBU} from "../src/EBU.sol";

contract InvMutTest is Test {
    EBU c;
    function setUp() public { c = new EBU(); }

    // fuzzed params: an address for the intended "counterparty" and a length for the _tos array
    // We cannot rely on a raw fuzzed address to exhibit failing behaviour, so we deploy a helper Reverter
    // and pass its address to c. We still fuzz the number of recipients and one recipient address/value.
    function testFuzz_property(address anyAddr, uint256 len) public {
        // keep len in a reasonable wide domain but non-zero to satisfy require(_tos.length > 0)
        uint256 n = bound(len, 1, 5);

        // construct arrays of length n
        address[] memory tos = new address[](n);
        uint256[] memory vals = new uint256[](n);
        for (uint i = 0; i < n; i++) {
            // use the fuzzed anyAddr as one of the recipients to keep inputs varied
            tos[i] = address(uint160(uint256(keccak256(abi.encodePacked(anyAddr, i)))));
            vals[i] = uint256(keccak256(abi.encodePacked(anyAddr, i, block.number))) & type(uint256).max;
        }

        // Deploy a callee that will revert when called (to distinguish reference vs mutant behavior)
        Reverter rev = new Reverter();

        // Call transfer and observe whether it reverts. For the reference C this should never revert and ok==true.
        bool ok;
        try c.transfer(address(0x1234), address(rev), tos, vals) {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property: reference C never reverts for any non-empty _tos; the mutant can revert when a callee fails.
        // Assert that transfer did NOT revert (this will hold for the reference implementation for all inputs,
        // and will fail for the mutant for some inputs because the mutant requires callees to succeed).
        assertTrue(ok);
    }
}

// adversarial callee that always reverts on any call
contract Reverter {
    fallback() external payable {
        revert("revert");
    }
    receive() external payable {
        revert("revert");
    }
}
